<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!role_can_access_page($user['role'],'communications')){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$id=filter_var($_POST['announcement_id']??null,FILTER_VALIDATE_INT);if(!$id){$_SESSION['error']='Select a valid announcement.';header('Location: ../?page=communications');exit;}$audiences=$user['role']==='Guardian'?['Everyone','Guardians']:['Everyone','Staff'];if(in_array($user['role'],['Administrator','Head'],true))$audiences=['Everyone','Staff','Guardians'];$in=implode(',',array_fill(0,count($audiences),'?'));$pdo=db();$stmt=$pdo->prepare('SELECT id FROM announcements WHERE id=? AND status=\'Published\' AND published_at<=NOW() AND audience IN ('.$in.')');$stmt->execute(array_merge([$id],$audiences));if(!$stmt->fetch()){http_response_code(404);exit('Announcement not found.');}try{$read=$pdo->prepare('INSERT INTO announcement_reads (announcement_id,user_id) VALUES (:announcement,:user) ON DUPLICATE KEY UPDATE read_at=VALUES(read_at)');$read->execute(['announcement'=>$id,'user'=>$user['id']]);$_SESSION['notice']='Announcement marked as read.';}catch(Throwable $e){error_log('Announcement read state failed: '.$e->getMessage());$_SESSION['error']='Could not update the read status.';}header('Location: ../?page=communications&tab=notices&view='.$id);exit;
